def cluster_texts(t):
 n=len(t)
 if n<3:return list(range(n))
 D=[prep(x if isinstance(x,str)else str(x))for x in t];k=np.array([len(x)>0 for x in D])
 if k.sum()<3:return[0]*n
 s=[x for x in D if x];r=[x for x,m in zip(t,k)if m]
 try:
  p=B if np.median([len(x)for x in s])<130 and np.mean(["\n"in x for x in r])<.08 and np.mean(["http"in x.lower()for x in r])<.03 else A;Z=embed(s);m=len(s)
  if m>6000:c=np.sort(np.random.default_rng(0).choice(m,6000,replace=False));l=np.array([np.bincount(v).argmax()for v in np.unique(core(Z[c],p),return_inverse=True)[1][NearestNeighbors(n_neighbors=5,metric="cosine").fit(Z[c]).kneighbors(Z)[1]]])
  else:l=core(Z,p,s)
 except Exception:l=MiniBatchKMeans(max(2,min(60,len(s)//40)),random_state=0,n_init=3).fit_predict(T(max_features=50000,sublinear_tf=True,dtype=f).fit_transform(s))
 l=np.unique(l,return_inverse=True)[1];w=[len(x.split())for x in s];e=np.bincount(l)[l]<2;g=[i for i,x in enumerate(r)if"preview.redd.it"in str(x)and(w[i]<4 or w[i]<11 and e[i])]
 if len(g)>19:l[g]=l.max()+1
 o=np.full(n,-1,np.int64);o[k]=l
 return[int(x)for x in o]
def make_app():
 a=FastAPI()
 @a.get("/health")
 def h():return{"status":"healthy"}
 @a.post("/cluster",response_model=R)
 def c(request:Q)->R:
  if not request.texts:raise HTTPException(status_code=400,detail="No texts provided")
  return R(cluster_ids=cluster_texts(request.texts))
 return a
